```go
package main

import "fmt"

func numbers() <-chan int {
    out := make(chan int)
    go func(destination chan<- int) {
        defer close(destination)
        for _, n := range []int{2, 4, 6} {
            destination <- n
        }
    }(out)
    return out
}

func main() {
    total := 0
    for n := range numbers() { total += n }
    fmt.Println(total)
}
```
The producer owns sending and closing. The caller only receives, and the output is `12`.
